#!/bin/bash
echo "" | base64 -d > /home/Agi/jogd/smoothtrack.py
echo "" | base64 -d > /home/Agi/jogd/run_smooth.sh
chmod +x /home/Agi/jogd/smoothtrack.py /home/Agi/jogd/run_smooth.sh
cp -f /home/Agi/jogd/run.sh /home/Agi/jogd/run_jogdact_latest.sh 2>/dev/null
cp -f /home/Agi/jogd/run_smooth.sh /home/Agi/jogd/run.sh
chmod +x /home/Agi/jogd/run.sh
ps -eo pid,cmd | grep -F '/jogd/jogd_act.py' | grep -v grep | awk '{print $1}' | xargs -r kill -9
echo "switched to smoothtrack; old engine killed"
exit 0
